SELECT assert_true((plan()->>'period_rake')::numeric=350 AND (plan()->>'earned_rake')::numeric=350 AND (plan()->>'house_rake')::numeric=50,'all banked rake is attributed, including explicit house earnings');
SELECT assert_true((SELECT (d->>'rake_in')::numeric=200 AND (d->>'payout')::numeric=170 AND (d->>'rate')::numeric=.85 FROM jsonb_array_elements(plan()->'basis_detail')d WHERE d->>'club_id'=u(2)::text),'midweek rates use each recorded earning agreement and one weighted display rate');
SELECT assert_true((SELECT (d->>'payout')::numeric=75 AND d->>'game_type'='mtt' FROM jsonb_array_elements(plan()->'basis_detail')d WHERE d->>'club_id'=u(3)::text),'tournament fees use charge-time club terms in their later recognized week');
SELECT assert_true((SELECT count(*)=2 FROM fn_union_club_rake_basis(u(1),'2026-09-07T07:00Z','2026-09-14T07:00Z',false)),'statement and close share the same current source plan');
SELECT assert_true(NOT has_function_privilege('service_role','fn_union_weekly_rakeback_close(uuid,timestamptz,timestamptz)','EXECUTE'),'Round 1 is private to the single coordinator');
SELECT assert_true(NOT has_function_privilege('authenticated','fn_accounting_union_earned_plan(uuid,timestamptz,timestamptz)','EXECUTE'),'the earning plan cannot leak invoices or agreements through a public RPC');
BEGIN;
INSERT INTO union_wallet_transactions(id,union_id,amount,tx_type,wallet,direction,created_at) VALUES(u(90),u(1),1,'rake','rake_wallet','credit','2026-09-12T00:00Z');
SELECT assert_true(refuses('SELECT plan()','55000'),'an unexplained bank credit blocks instead of becoming retained revenue');
SELECT assert_true(close_week()->>'success'='false' AND (SELECT rake_wallet=350 FROM union_wallets WHERE union_id=u(1)),'uncertified source close refuses before balances change');
ROLLBACK;
BEGIN;
UPDATE union_wallet_transactions SET created_at='2026-09-15T12:00Z' WHERE id=u(50);
SELECT assert_true(refuses('SELECT plan()','55000'),'moving a bank credit to another week cannot hide the receipt mismatch');
ROLLBACK;
BEGIN;
UPDATE union_wallet_transactions SET union_id=u(999) WHERE id=u(50);
SELECT assert_true(refuses('SELECT plan()','55000'),'moving a bank credit to another union cannot hide the receipt mismatch');
ROLLBACK;
BEGIN;
UPDATE accounting_cash_rake_sources SET rake_credit=99 WHERE id=u(60);
SELECT assert_true(refuses('SELECT plan()','55000'),'cash source sum must equal its exact real bank deposit');
ROLLBACK;
BEGIN;
UPDATE accounting_cash_rake_sources SET contract=jsonb_set(contract,'{union_agreement}',(SELECT contract->'union_agreement' FROM accounting_cash_rake_sources WHERE id=u(60))) WHERE id=u(62);
SELECT assert_true(refuses('SELECT plan()','55000'),'a superseded rate cannot be substituted for the earning-time agreement');
ROLLBACK;
BEGIN;
UPDATE accounting_tournament_fee_recognitions SET status='banked_accrual_deferred';
SELECT assert_true(refuses('SELECT plan()','55000'),'a banked but deferred tournament fee blocks the week');
ROLLBACK;
BEGIN;
UPDATE accounting_tournament_recognized_sources SET disposition='refunded';
SELECT assert_true(refuses('SELECT plan()','55000'),'a refunded contributor cannot silently remain in the earned bank total');
ROLLBACK;
BEGIN;
INSERT INTO accounting_cash_rake_sources SELECT u(99),u(98),u(106),u(2),u(1),u(1),'2026-09-12T12:00Z',1,contract(2,106,1,'2026-09-12T12:00Z',2);
SELECT assert_true(refuses('SELECT plan()','55000'),'an extra source without its bank receipt refuses');
ROLLBACK;
BEGIN;
UPDATE accounting_cash_rake_sources SET contract=jsonb_set(contract,'{is_union_house}','true') WHERE id=u(60);
SELECT assert_true(refuses('SELECT plan()','55000'),'an ordinary club cannot be relabeled as the union house');
ROLLBACK;
BEGIN;
UPDATE union_wallets SET rake_wallet=349 WHERE union_id=u(1);
SELECT assert_true(close_week()->>'error'='insufficient_rake_treasury','one-chip short treasury refuses the whole close');
SELECT assert_true((SELECT rake_wallet=349 AND chip_balance=10 FROM union_wallets WHERE union_id=u(1)) AND (SELECT sum(chip_treasury)=0 FROM clubs),'underfunded close leaves every bank and club unchanged');
ROLLBACK;
CREATE FUNCTION test_delivery_failure() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.user_id=u(102) THEN RAISE EXCEPTION 'invoice delivery failed';END IF;RETURN NEW;END$$;
CREATE TRIGGER test_delivery_failure BEFORE INSERT ON notifications FOR EACH ROW EXECUTE FUNCTION test_delivery_failure();
SELECT assert_true(close_week()->>'success'='false','actual Messenger notification failure refuses the entire union close');
SELECT assert_true((SELECT rake_wallet=350 AND chip_balance=10 FROM union_wallets WHERE union_id=u(1)) AND (SELECT sum(chip_treasury)=0 FROM clubs WHERE id IN(u(1),u(2),u(3))) AND NOT EXISTS(SELECT 1 FROM chip_ledger WHERE union_id=u(1)),'delivery failure rolls back bank, clubs and journal together');
DROP TRIGGER test_delivery_failure ON notifications;
SELECT assert_true(close_week()->>'success'='true','a fully funded source-certified close succeeds');
SELECT assert_true((SELECT rake_wallet=0 AND chip_balance=115 FROM union_wallets WHERE union_id=u(1)) AND (SELECT chip_treasury=170 FROM clubs WHERE id=u(2)) AND (SELECT chip_treasury=75 FROM clubs WHERE id=u(3)),'350 debited equals 245 paid plus 105 retained with exact cents');
SELECT assert_true((SELECT count(*)=2 FROM chip_ledger WHERE union_id=u(1) AND to_type='club_treasury') AND (SELECT count(*)=2 FROM settlement_invoices i JOIN chip_ledger l ON l.id=i.source_ledger_id WHERE l.union_id=u(1) AND l.to_type='club_treasury' AND i.status='paid' AND i.message_sent),'each real union-to-club journal row has its paid invoice and delivery');
SELECT assert_true((SELECT count(*)=2 FROM accounting_invoice_deliveries d JOIN settlement_invoices i ON i.id=d.invoice_id JOIN chip_ledger l ON l.id=i.source_ledger_id WHERE l.union_id=u(1) AND l.to_type='club_treasury' AND d.recipient_id IN(u(101),u(102)) AND d.delivery_mode='immediate'),'each club receives its own weekly union receipt, with no per-agent payout messages');
SELECT assert_true(COALESCE(current_setting('app.ledger_autoskip_clubs',true),'')='' AND COALESCE(current_setting('app.ledger_autoskip_union_wallets',true),'')='','weekly close restores journal settings for later operations');
SELECT assert_true(close_week()->>'error'='already_executed' AND (SELECT rake_wallet=0 AND chip_balance=115 FROM union_wallets WHERE union_id=u(1)),'retry cannot pay the same book twice');
BEGIN;
UPDATE accounting_cash_rake_sources SET contract=jsonb_set(contract,'{union_agreement,terms,club_commission_rate}','0.1');
SELECT assert_true((SELECT sum(payout)=245 FROM fn_union_club_rake_basis(u(1),'2026-09-07T07:00Z','2026-09-14T07:00Z',false)),'final statement keeps its frozen paid basis even if upstream source data later drifts');
ROLLBACK;
